package io.github.jesterportfolio.hearth.quest;

import io.github.jesterportfolio.hearth.crafting.*;
import io.github.jesterportfolio.hearth.persistence.*;
import io.github.jesterportfolio.hearth.inventory.InventoryPayload;
import org.junit.jupiter.api.Test;
import java.util.*;
import java.util.concurrent.*;
import java.util.function.*;
import static org.junit.jupiter.api.Assertions.*;

final class CraftingQuestTest {
    static CraftContent recipes(){return new CraftContent(Map.of("planks",new CraftContent.Recipe("planks","판자","minecraft:oak_planks",List.of("OAK_LOG","AIR","AIR","AIR","AIR","AIR","AIR","AIR","AIR"))),Map.of("bench",new CraftContent.Facility("bench",13,64,13,List.of("planks"))));}
    static QuestCatalog catalog(boolean repeat){var a=QuestCatalogTest.quest("survey_marker","guide");var b=QuestCatalogTest.quest("path_marker","guide");
        var goal=new HashMap<>(Map.of("min-x",12,"max-x",14,"min-y",64,"max-y",67,"min-z",12,"max-z",14,"interaction","craft:bench:planks","description","판자를 제작하세요"));
        if(repeat){a.remove("objective");a.put("objectives",List.of(goal,goal));}else a.put("objective",goal);b.put("objective",goal);b.put("completion-mode","automatic");return QuestCatalog.parse(List.of(QuestCatalogTest.npc("guide",3)),List.of(a,b));}
    final PersonalQuestTest.Fixture f=new PersonalQuestTest.Fixture(true);final QuestCatalog catalog=catalog(false);final ServerProgressAccess.Context ctx=f.ctx(f.a,f.p);
    final CraftingAction actions=new CraftingAction(f.queue::add,()->{},InventoryPayload::equals);final CraftingQuest bridge=new CraftingQuest(f.quests,catalog,recipes(),f.queue::add,()->{});
    final class Port implements CraftingAction.Port {
        final ServerProgressAccess.Context context;InventoryPayload value=PersonalQuestTestPayload(1);CraftingQuest.Prepared prepared;CraftingQuest service=bridge;int applied;boolean live=true;String source="craft:bench:planks";
        Port(ServerProgressAccess.Context context){this.context=context;}
        public UUID run(){return context.storyRunId();}public UUID player(){return context.playerId();}public String source(){return source;}public boolean valid(){return live&&(prepared==null||service.valid(prepared));}
        public InventoryPayload capture(){return value;}public InventoryPayload plan(InventoryPayload before){return PersonalQuestTestPayload(2);}public void apply(InventoryPayload value){this.value=value;applied++;}public void changed(){}public void hold(){throw new AssertionError("Unexpected apply failure");}
    }
    static InventoryPayload PersonalQuestTestPayload(int n){var slots=new byte[41][];slots[0]=new byte[]{(byte)n};return InventoryPayload.pack(slots);}
    void seed(ServerProgressAccess.Context c,String quest){f.store.rows.put(f.store.key(c,quest),new QuestStore.Saved(QuestStore.Phase.ACTIVE,0));}
    CraftingQuest.Prepared prepare(CraftingQuest service,Port p,CraftingAction.Ticket ticket){var work=service.prepare(p.context,"bench","planks",ticket,()->p.live,()->p.live,id->true);f.pump();var ready=work.toCompletableFuture().join();p.service=service;p.prepared=ready;return ready;}
    void apply(CraftingAction.Ticket t){var work=actions.confirm(t);f.pump();assertFalse(work.toCompletableFuture().isCompletedExceptionally());}
    @Test void sourceSaveFinishesBeforeQuestWriteAndDuplicateReceiptDoesNotAdvanceAgain(){
        seed(ctx,"survey_marker");var p=new Port(ctx);var ticket=actions.preview(p);var prepared=prepare(bridge,p,ticket);apply(ticket);var save=new CompletableFuture<Void>();var work=bridge.complete(prepared,()->save);assertSame(work,bridge.complete(prepared,()->{throw new AssertionError();}));f.pump();assertEquals(0,f.store.pending.size());assertFalse(work.toCompletableFuture().isDone());var barrier=bridge.barrier(f.a).toCompletableFuture();assertFalse(barrier.isDone());save.complete(null);f.pump();assertEquals(1,f.store.pending.size());assertFalse(work.toCompletableFuture().isDone());f.commit(0);assertEquals(1,work.toCompletableFuture().join().size());assertTrue(barrier.isDone());assertFalse(barrier.isCompletedExceptionally());assertEquals(QuestStore.Phase.REPORT_READY,f.store.rows.get(f.store.key(ctx,"survey_marker")).phase());assertEquals(1,f.store.pending.size());
    }
    @Test void unacceptedQuestDoesNotCauseWriteOrInventoryFlush(){var p=new Port(ctx);var ticket=actions.preview(p);var prepared=prepare(bridge,p,ticket);assertFalse(prepared.active());apply(ticket);var work=bridge.complete(prepared,()->{throw new AssertionError("No quest checkpoint");});f.pump();assertTrue(work.toCompletableFuture().join().isEmpty());assertEquals(0,f.store.pending.size());}
    @Test void visitCannotSatisfyCraftGoalAndCompletionModesRemainDistinct(){seed(ctx,"survey_marker");seed(ctx,"path_marker");var p=new Port(ctx);var ticket=actions.preview(p);var prepared=prepare(bridge,p,ticket);apply(ticket);var work=bridge.complete(prepared,()->CompletableFuture.completedFuture(null));f.pump();for(int i=0;i<2;i++)f.commit(i);assertTrue(work.toCompletableFuture().isDone());assertEquals(QuestStore.Phase.REPORT_READY,f.store.rows.get(f.store.key(ctx,"survey_marker")).phase());assertEquals(QuestStore.Phase.COMPLETED,f.store.rows.get(f.store.key(ctx,"path_marker")).phase());}
    @Test void inventorySaveFailureLeavesQuestOriginalAndHoldWithoutAffectingOtherRun(){seed(ctx,"survey_marker");var p=new Port(ctx);var t=actions.preview(p);var ready=prepare(bridge,p,t);apply(t);var work=bridge.complete(ready,()->CompletableFuture.failedFuture(new StorageFailure("inventory","WRITE_FAILED")));f.pump();assertTrue(work.toCompletableFuture().isCompletedExceptionally());assertEquals(0,f.store.pending.size());assertEquals(0,f.store.rows.get(f.store.key(ctx,"survey_marker")).revision());assertTrue(bridge.held(ctx));assertTrue(bridge.barrier(f.a).toCompletableFuture().isCompletedExceptionally());assertTrue(bridge.settled(f.b));assertEquals(1,p.applied);}
    @Test void questWriteFailureKeepsOriginalAndDoesNotReapplyInventory(){seed(ctx,"survey_marker");var p=new Port(ctx);var t=actions.preview(p);var ready=prepare(bridge,p,t);apply(t);var work=bridge.complete(ready,()->CompletableFuture.completedFuture(null));f.pump();f.store.pending.get(0).completeExceptionally(new StorageFailure("quest","WRITE_FAILED"));f.pump();assertTrue(work.toCompletableFuture().isCompletedExceptionally());assertEquals(0,f.store.rows.get(f.store.key(ctx,"survey_marker")).revision());assertTrue(bridge.held(ctx));assertEquals(1,p.applied);assertSame(work,bridge.complete(ready,()->{throw new AssertionError();}));}
    @Test void sessionInvalidationDuringSaveRejectsLateProgress(){seed(ctx,"survey_marker");var p=new Port(ctx);var t=actions.preview(p);var ready=prepare(bridge,p,t);apply(t);var save=new CompletableFuture<Void>();var work=bridge.complete(ready,()->save);p.live=false;save.complete(null);f.pump();assertTrue(work.toCompletableFuture().isCompletedExceptionally());assertTrue(bridge.settled(f.a));assertTrue(f.store.pending.isEmpty());}
    @Test void wrongReceiptContextAndReferenceAreRejectedBeforeReads(){var other=new Port(f.ctx(f.b,f.p));var t=actions.preview(other);int reads=f.store.reads;var wrong=bridge.prepare(ctx,"bench","planks",t,()->true,()->true,id->true);assertTrue(wrong.toCompletableFuture().isCompletedExceptionally());other.source="craft:bench:other";t=actions.preview(other);assertTrue(bridge.prepare(other.context,"bench","planks",t,()->true,()->true,id->true).toCompletableFuture().isCompletedExceptionally());assertEquals(reads,f.store.reads);}
    @Test void samePlayerOtherRunAndSameRunOtherPlayerRemainUnchanged(){var p2=f.ctx(f.a,f.p2);var other=f.ctx(f.b,f.p);for(var c:List.of(ctx,p2,other))seed(c,"survey_marker");var p=new Port(ctx);var t=actions.preview(p);var ready=prepare(bridge,p,t);apply(t);var work=bridge.complete(ready,()->CompletableFuture.completedFuture(null));f.pump();f.commit(0);assertFalse(work.toCompletableFuture().isCompletedExceptionally());assertEquals(0,f.store.rows.get(f.store.key(p2,"survey_marker")).revision());assertEquals(0,f.store.rows.get(f.store.key(other,"survey_marker")).revision());}
    @Test void preparationQueryFailureDoesNotApplyOrInitializeQuest(){f.store.deferReads=true;var p=new Port(ctx);var work=bridge.prepare(ctx,"bench","planks",actions.preview(p),()->p.live,()->p.live,id->true);f.pump();f.store.readResults.get(0).completeExceptionally(new StorageFailure("quest","READ_FAILED"));f.pump();assertTrue(work.toCompletableFuture().isCompletedExceptionally());assertEquals(0,p.applied);assertTrue(f.store.rows.isEmpty());}
    @Test void unavailableRecipeAndOutOfBoundsFacilityFailAtLoading(){var bad=recipes();var different=new CraftContent(bad.recipes(),Map.of("bench",new CraftContent.Facility("bench",6,64,6,List.of("planks"))));assertThrows(IllegalArgumentException.class,()->new CraftingQuest(f.quests,catalog,different,f.queue::add,()->{}));var unknown=QuestCatalogTest.quest("survey_marker","guide");var bounds=new HashMap<>(Map.of("min-x",12,"max-x",14,"min-y",64,"max-y",67,"min-z",12,"max-z",14,"interaction","craft:bench:missing"));unknown.put("objective",bounds);var broken=QuestCatalog.parse(List.of(QuestCatalogTest.npc("guide",3)),List.of(unknown));assertThrows(IllegalArgumentException.class,()->new CraftingQuest(f.quests,broken,recipes(),f.queue::add,()->{}));}
    @Test void replacedQuestSessionRejectsOldConfirmation(){seed(ctx,"survey_marker");var p=new Port(ctx);var ticket=actions.preview(p);prepare(bridge,p,ticket);f.quests.open(ctx,"survey_marker",new Object(),()->true);f.pump();var applied=actions.confirm(ticket);f.pump();assertTrue(applied.toCompletableFuture().isCompletedExceptionally());assertEquals(0,p.applied);assertTrue(f.store.pending.isEmpty());}
    @Test void disconnectDuringPreparationDoesNotApplyLateRead(){f.store.deferReads=true;var p=new Port(ctx);var work=bridge.prepare(ctx,"bench","planks",actions.preview(p),()->p.live,()->p.live,id->true);f.pump();p.live=false;f.store.readResults.get(0).complete(new QuestStore.Saved(QuestStore.Phase.NOT_ACCEPTED,-1));f.pump();assertTrue(work.toCompletableFuture().isCompletedExceptionally());assertEquals(0,p.applied);assertTrue(f.store.pending.isEmpty());}
    @Test void oneReceiptCannotAdvanceConsecutiveIdenticalCraftGoalsTwice(){var repeated=new CraftingQuest(f.quests,catalog(true),recipes(),f.queue::add,()->{});seed(ctx,"survey_marker");var p=new Port(ctx);var ticket=actions.preview(p);var ready=prepare(repeated,p,ticket);apply(ticket);var work=repeated.complete(ready,()->CompletableFuture.completedFuture(null));f.pump();f.commit(0);assertFalse(work.toCompletableFuture().isCompletedExceptionally());assertEquals(1,f.store.rows.get(f.store.key(ctx,"survey_marker")).objectiveIndex());assertSame(work,repeated.complete(ready,()->{throw new AssertionError();}));assertEquals(1,p.applied);assertEquals(1,f.store.pending.size());}
    @Test void accessChangeBeforeConfirmationRejectsApply(){seed(ctx,"survey_marker");var p=new Port(ctx);var ticket=actions.preview(p);var access=new java.util.concurrent.atomic.AtomicBoolean(true);var ready=bridge.prepare(ctx,"bench","planks",ticket,()->p.live,()->p.live,id->access.get());f.pump();p.prepared=ready.toCompletableFuture().join();access.set(false);var applied=actions.confirm(ticket);f.pump();assertTrue(applied.toCompletableFuture().isCompletedExceptionally());assertEquals(0,p.applied);assertTrue(f.store.pending.isEmpty());}
    @Test void oldAppliedReceiptCannotBePreparedForNewProgress(){var p=new Port(ctx);var ticket=actions.preview(p);apply(ticket);assertTrue(bridge.prepare(ctx,"bench","planks",ticket,()->true,()->true,id->true).toCompletableFuture().isCompletedExceptionally());}
    @Test void unconfirmedReceiptCannotGrantObjective(){seed(ctx,"survey_marker");var p=new Port(ctx);var ready=prepare(bridge,p,actions.preview(p));var work=bridge.complete(ready,()->{throw new AssertionError();});assertTrue(work.toCompletableFuture().isCompletedExceptionally());assertEquals(0,p.applied);assertTrue(f.store.pending.isEmpty());}
}
